import React from 'react';
import { useNavigate } from 'react-router-dom';

const SuccessMessage = ({ formData }) => {
    const navigate = useNavigate();

    const clickHandler = (event) => {
        event.preventDefault();
        navigate('/takequiz');
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-purple-400 via-indigo-500 to-blue-600">
            <div className="bg-white rounded-lg shadow-lg p-8 max-w-xl w-full">
                {/* Title */}
                <h2 className="text-4xl font-semibold text-center text-gray-900 mb-6">
                    Quiz Created Successfully!
                </h2>

                {/* Quiz Details */}
                <h4 className="text-lg font-medium text-center text-gray-700 mb-8">
                    Quiz Details
                </h4>

                <div className="text-gray-700 space-y-4 mb-8">
                    <p><strong>Name:</strong> {formData.name}</p>
                    <p><strong>Exam:</strong> {formData.exam}</p>
                    <p><strong>Difficulty Levels:</strong> {formData.difficultyLevels.join(', ')}</p>
                    <p><strong>Class / Year:</strong> {formData.classYear}</p>
                    <p><strong>Subjects:</strong> {formData.subjects.join(', ')}</p>
                    <p><strong>Topics:</strong> {formData.topics.join(', ')}</p>
                    <p><strong>Quiz Mode:</strong> {formData.quizMode}</p>
                    <p><strong>Number of Questions:</strong> {formData.numberOfQuestions}</p>

                    {formData.addHints && <p><strong>Hints:</strong> Enabled</p>}
                    {formData.answerExplanation ?
                        <p><strong>Answer Explanation:</strong> Enabled</p> :
                        <p><strong>Answer Explanation:</strong> Disabled</p>}
                    {formData.breakIntoSubtopics ?
                        <p><strong>Break Into Subtopics:</strong> Enabled</p> :
                        <p><strong>Break Into Subtopics:</strong> Disabled</p>}
                </div>

                {/* Action Buttons */}
                <div className="space-y-4">
                    <button
                        className="w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-3 rounded-lg text-lg font-medium shadow-md transition-all hover:scale-105 focus:outline-none"
                        onClick={clickHandler}
                    >
                        Start Quiz
                    </button>

                    <button
                        className="w-full bg-gradient-to-r from-gray-300 to-gray-400 text-gray-800 py-3 rounded-lg text-lg font-medium shadow-md transition-all hover:scale-105 focus:outline-none"
                        onClick={() => window.location.reload()}
                    >
                        Create Another Quiz
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SuccessMessage;
